import { describe, expect, it } from 'vitest';
import { customHeadingIdSourceLines, preprocessCustomHeadingIds, } from './preprocessCustomHeadingIds.js';
describe('preprocessCustomHeadingIds', () => {
    it('converts top-level headings with custom ids', () => {
        expect(preprocessCustomHeadingIds('## Heading {#custom-id}')).toBe('<h2 id="custom-id">\nHeading\n</h2>');
    });
    it('converts headings indented by up to 3 spaces and preserves indentation', () => {
        expect(preprocessCustomHeadingIds('  ## Heading {#custom_id}')).toBe('  <h2 id="custom_id">\n  Heading\n  </h2>');
        expect(preprocessCustomHeadingIds(' # A {#a}')).toBe(' <h1 id="a">\n A\n </h1>');
        expect(preprocessCustomHeadingIds('   ### B {#b}')).toBe('   <h3 id="b">\n   B\n   </h3>');
    });
    it('converts indented headings inside JSX components', () => {
        const input = `<Update label="March 2026">
  ## Release Notes {#release_notes}

  Content
</Update>`;
        const output = preprocessCustomHeadingIds(input);
        expect(output).toContain('  <h2 id="release_notes">\n  Release Notes\n  </h2>');
        expect(output).not.toContain('{#');
    });
    it('leaves headings indented by 4 or more spaces alone', () => {
        const input = '    ## Heading {#custom-id}';
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('converts headings at any indent inside an <MDX> block', () => {
        const input = `{variant === "fos" ? (
  <MDX>
    ### Request a token {#request-token}

    Body
  </MDX>
) : null}

    ## Still code {#not-converted}`;
        const output = preprocessCustomHeadingIds(input);
        expect(output).toContain('    <h3 id="request-token">\n    Request a token\n    </h3>');
        // depth is back to 0 after </MDX>: 4-space indent is an indented code block again
        expect(output).toContain('    ## Still code {#not-converted}');
    });
    it('leaves code fences inside an <MDX> block alone', () => {
        const input = `<MDX>
    \`\`\`md
    ## Heading {#custom-id}
    \`\`\`
</MDX>`;
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('ignores an unrelated MDX-prefixed tag', () => {
        const input = '<MDXProvider>\n    ## Heading {#custom-id}\n</MDXProvider>';
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('does not treat a self-closing <MDX /> as opening a block', () => {
        // a self-closing tag has no body; the any-indent rule must not stay on for the rest of the file
        for (const tag of ['<MDX />', '<MDX/>', '<MDX className="x" />']) {
            const input = `${tag}\n\n    ## Still code {#not-converted}`;
            expect(preprocessCustomHeadingIds(input)).toBe(input);
        }
    });
    it('leaves tab-indented headings alone', () => {
        const input = '\t## Heading {#custom-id}';
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('leaves indented headings inside code fences alone', () => {
        const input = `\`\`\`md
  ## Heading {#custom-id}
\`\`\``;
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('leaves headings inside indented code fences alone', () => {
        const input = `  \`\`\`md
  ## Heading {#custom-id}
  \`\`\``;
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('converts headings after a comment whose closing fence shares a line with */}', () => {
        const input = `{/* Note

  \`\`\`python
  run.log({'loss': 0.2})
  \`\`\` */}

## After {#after}`;
        expect(preprocessCustomHeadingIds(input)).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('converts headings after a comment whose closing fence is on its own line', () => {
        const input = `{/* Note

  \`\`\`python
  run.log({'loss': 0.2})
  \`\`\`
  */}

## After {#after}`;
        expect(preprocessCustomHeadingIds(input)).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('converts headings after an inline comment whose closing fence shares a line with */}', () => {
        const input = `<Note>{/* Note

\`\`\`python
x = 1
\`\`\` */}</Note>

## After {#after}`;
        expect(preprocessCustomHeadingIds(input)).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('ignores comment openers inside inline code', () => {
        expect(preprocessCustomHeadingIds('Use `{/*` to open a comment.\n\n## After {#after}')).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('tracks a comment reopened on the line that closes the previous one', () => {
        const input = '{/* one\n*/} {/* two\n## Hidden {#hidden}\n*/}\n\n## After {#after}';
        const output = preprocessCustomHeadingIds(input);
        expect(output).toContain('## Hidden {#hidden}');
        expect(output).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('ignores comment openers inside quoted attribute values', () => {
        expect(preprocessCustomHeadingIds('<Note title="{/*">\nBody\n</Note>\n\n## After {#after}')).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('tracks a comment opened between apostrophes in prose', () => {
        const input = "Don't miss {/* it's hidden\n## Hidden {#hidden}\n*/}\n\n## After {#after}";
        const output = preprocessCustomHeadingIds(input);
        expect(output).toContain('## Hidden {#hidden}');
        expect(output).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('counts an <MDX> tag that shares a line with a comment', () => {
        const input = '<MDX>{/* note\n*/}\n    ## Heading {#heading}\n</MDX>';
        expect(preprocessCustomHeadingIds(input)).toContain('    <h2 id="heading">\n    Heading\n    </h2>');
    });
    it('ignores <MDX> tags inside comments', () => {
        for (const input of [
            '{/* <MDX> */}\n\n    ## Still code {#not-converted}',
            '{/*\n<MDX>\n*/}\n\n    ## Still code {#not-converted}',
        ]) {
            expect(preprocessCustomHeadingIds(input)).toBe(input);
        }
    });
    it('ends a comment at */ regardless of what precedes the closing brace', () => {
        for (const comment of [
            '{/* note */ }',
            '{/*\n  note\n*/\n}',
            '<Note data-x={/* x */ 1}>\nBody\n</Note>',
        ]) {
            expect(preprocessCustomHeadingIds(`${comment}\n\n## After {#after}`)).toContain('<h2 id="after">\nAfter\n</h2>');
        }
    });
    it('converts headings after a single-line comment', () => {
        expect(preprocessCustomHeadingIds('{/* Note */}\n\n## After {#after}')).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('leaves headings inside a comment alone', () => {
        const input = '{/*\n## Heading {#custom-id}\n*/}';
        expect(preprocessCustomHeadingIds(input)).toBe(input);
    });
    it('does not treat a comment opener inside a code fence as a comment', () => {
        const input = `\`\`\`mdx
{/* Note
\`\`\`

## After {#after}`;
        expect(preprocessCustomHeadingIds(input)).toContain('<h2 id="after">\nAfter\n</h2>');
    });
    it('normalizes ids by default', () => {
        expect(preprocessCustomHeadingIds('  ## Heading {#my id!}')).toBe('  <h2 id="my-id">\n  Heading\n  </h2>');
    });
    it('preserves original ids when preserveOriginal is set', () => {
        expect(preprocessCustomHeadingIds('  ## Heading {#my_id}', { preserveOriginal: true })).toBe('  <h2 id="my_id">\n  Heading\n  </h2>');
    });
});
describe('customHeadingIdSourceLines', () => {
    it('maps each output line to the source line it came from', () => {
        const content = [
            '# Title {#title}',
            'Body',
            '```',
            '## Code {#code}',
            '```',
            '## End {#end}',
        ].join('\n');
        const sourceLines = customHeadingIdSourceLines(content);
        expect(sourceLines).toEqual([1, 1, 1, 2, 3, 4, 5, 6, 6, 6]);
        expect(sourceLines).toHaveLength(preprocessCustomHeadingIds(content).split('\n').length);
    });
});
